import inspect

TYPES = {int: "integer", float: "number", str: "string", bool: "boolean"}

def tool_schema(fn):
    sig = inspect.signature(fn)
    props, required = {}, []
    for name, p in sig.parameters.items():
        props[name] = {"type": TYPES[p.annotation]}
        if p.default is inspect.Parameter.empty:
            required.append(name)
    doc = (inspect.getdoc(fn) or "").split("\n")[0]
    return {"name": fn.__name__, "description": doc,
            "parameters": {"type": "object", "properties": props, "required": required}}

PY = {"integer": int, "number": (int, float), "string": str, "boolean": bool}

def validate_args(schema, args):
    params = schema["parameters"]
    errors = []
    for name in params["required"]:
        if name not in args:
            errors.append(f"missing argument '{name}'")
    for name, value in args.items():
        if name not in params["properties"]:
            errors.append(f"unknown argument '{name}'")
            continue
        want = params["properties"][name]["type"]
        ok = isinstance(value, PY[want]) and not (want != "boolean" and isinstance(value, bool))
        if not ok:
            errors.append(f"'{name}' should be {want}, got {type(value).__name__}")
    return errors

def get_weather(city: str, days: int = 1):
    """Forecast for a city, for 1-7 days."""
    if not 1 <= days <= 7:
        raise ValueError("days must be between 1 and 7")
    return f"{city}: 31 C, clear for {days} day(s)"

def read_log(path: str):
    """Return the contents of a log file."""
    return "INFO ok\n" * 500

TOOLS = {"get_weather": get_weather, "read_log": read_log}

def scripted(actions):
    """A fake model that replies from a list of actions and records what it saw."""
    seen = []
    it = iter(actions)
    def model(messages):
        seen.append([m["content"] for m in messages])
        return next(it)
    model.seen = seen
    return model


def run_agent(model, tools, task, max_steps=6, max_obs=200):
    schemas = {name: tool_schema(fn) for name, fn in tools.items()}
    messages = [{"role": "user", "content": task}]
    last_call = None
    for step in range(1, max_steps + 1):
        action = model(messages)
        if "answer" in action:
            return {"status": "answered", "answer": action["answer"], "steps": step, "messages": messages}
        call = (action["tool"], sorted(action.get("args", {}).items()))
        if call == last_call:
            return {"status": "stuck", "answer": None, "steps": step, "messages": messages}
        last_call = call
        name, args = action["tool"], action.get("args", {})
        if name not in tools:
            obs = f"error: unknown tool '{name}'"
        else:
            errors = validate_args(schemas[name], args)
            if errors:
                obs = "error: " + "; ".join(errors)
            else:
                try:
                    obs = str(tools[name](**args))
                except Exception as e:
                    obs = f"error: {type(e).__name__}: {e}"
        if len(obs) > max_obs:
            obs = obs[:max_obs] + f" ...[{len(obs) - max_obs} chars truncated]"
        messages.append({"role": "tool", "content": obs})
    return {"status": "max_steps", "answer": None, "steps": max_steps, "messages": messages}
